import { ReviewFinding, ReviewReport } from "@effect-agent/pr-review";
import { describe, expect, it } from "@effect/vitest";

import {
  defaultReviewPresentation,
  renderFindingBody,
  renderReviewPauseBody,
  renderReviewBody,
  renderReviewFailureBody,
  withReviewMarker,
  withReviewPauseMarker,
} from "../src/presentation.ts";

const headRevision = "abcdef0123456789abcdef0123456789abcdef01";

const anchoredFinding = ReviewFinding.make({
  path: "src/projection.ts",
  line: 1909,
  severity: "blocking",
  category: "correctness",
  title: "Retired source generations never settle",
  body: "The retired delivery remains projection-pending forever.",
});

describe("review presentation", () => {
  it("renders the inline finding once, without duplicating the agent handoff", () => {
    expect(renderFindingBody(anchoredFinding)).toMatchInlineSnapshot(`
      "**[🛑 blocking · correctness] Retired source generations never settle**

      The retired delivery remains projection-pending forever."
    `);
  });

  it("renders a severity callout, review stats, unanchored findings, and a batch prompt", () => {
    const unanchoredFinding = ReviewFinding.make({
      path: "src/auth.ts",
      severity: "important",
      category: "security",
      title: "Authorization is not enforced",
      body: "The new route accepts requests without checking the caller.",
    });
    const body = renderReviewBody({
      report: ReviewReport.make({
        summary: "The change has two actionable defects.",
        findings: [anchoredFinding, unanchoredFinding],
      }),
      automatic: false,
      automaticReviewsRemaining: 2,
      scope: "full",
      reviewedFiles: 2,
      unreviewedFiles: 1,
      ignoredFiles: 3,
      shards: 2,
      inputTokens: 12_345,
      uncachedInputTokens: 10_000,
      cachedInputTokens: 2_000,
      cacheWriteInputTokens: 345,
      outputTokens: 678,
      estimatedCost: {
        microusd: 62_940,
        label: "GPT-5.6 Sol",
        url: "https://developers.openai.com/api/docs/models/gpt-5.6-sol",
      },
      headRevision,
    });

    expect(body).toContain("> [!CAUTION]\n> **1 blocking finding.** Do not merge");
    expect(body).toContain(
      "| **Full diff** | 2 reviewed · 1 unavailable · 3 ignored | 🛑 1 blocking · ⚠️ 1 important |",
    );
    expect(body).toContain("<summary>Findings without an inline anchor (1)</summary>");
    expect(body).toContain("**[⚠️ important · security] Authorization is not enforced**");
    expect(body).toContain("<summary>🤖 Prompt for all 2 findings with AI agents</summary>");
    expect(body).toContain(
      '<sub>2 parallel review shards · 12,345 input (10,000 uncached · 2,000 cached · 345 cache write) / 678 output tokens · ≈ $0.0629 at <a href="https://developers.openai.com/api/docs/models/gpt-5.6-sol">GPT-5.6 Sol rates</a> · reviewed at <code>abcdef0</code> · 2 automatic reviews remain</sub>',
    );
  });

  it("renders a clean review as a compact receipt", () => {
    const body = withReviewMarker(
      defaultReviewPresentation.renderReview({
        report: ReviewReport.make({
          summary: "No actionable defects found in the supplied diff.",
          findings: [],
        }),
        automatic: true,
        automaticReviewsRemaining: 0,
        scope: "incremental",
        reviewedFiles: 3,
        unreviewedFiles: 0,
        ignoredFiles: 2,
        shards: 1,
        inputTokens: 2_267,
        uncachedInputTokens: 2_000,
        cachedInputTokens: 200,
        cacheWriteInputTokens: 67,
        outputTokens: 456,
        estimatedCost: {
          microusd: 18_188,
          label: "GPT-5.6 Sol",
          url: "https://developers.openai.com/api/docs/models/gpt-5.6-sol",
        },
        headRevision,
      }),
      true,
    );

    expect(body).toMatchInlineSnapshot(`
      "## Effect Agent review

      > [!TIP]
      > **No actionable findings.**

      | Scope | Files | Findings |
      | :-- | :-- | :-- |
      | **Incremental** | 3 reviewed · 2 ignored | ✅ None |

      > [!NOTE]
      > **Automatic reviews are paused for this pull request.**
      > Further pushes will not start another review. Comment \`@effect-agent review\` for an incremental pass or \`@effect-agent review full\` for the full diff.

      ### Summary

      No actionable defects found in the supplied diff.

      <sub>1 review shard · 2,267 input (2,000 uncached · 200 cached · 67 cache write) / 456 output tokens · ≈ $0.0182 at <a href="https://developers.openai.com/api/docs/models/gpt-5.6-sol">GPT-5.6 Sol rates</a> · reviewed at <code>abcdef0</code></sub>

      <!-- effect-agent-review:v2 automatic=true completed=true -->"
    `);
  });

  it("keeps attempt accounting outside replaceable presentation", () => {
    expect(withReviewMarker("Custom presentation", false, false)).toBe(
      "Custom presentation\n\n<!-- effect-agent-review:v2 automatic=false completed=false -->",
    );
  });

  it("renders a one-time closing review without a model call", () => {
    const body = withReviewPauseMarker(
      renderReviewPauseBody({
        automaticReviewLimit: 2,
        automaticAttempts: 2,
        lastCompletedRevision: "840c401c8e3103efcb70bd602e88b85834bd021d",
        headRevision,
      }),
      2,
    );

    expect(body).toMatchInlineSnapshot(`
      "## Effect Agent review

      > [!NOTE]
      > **Automatic reviews are paused for this pull request.**
      > The configured automatic review limit has been reached. No model call was made for this update.

      | Automatic attempts | Last completed review | Current head |
      | :-- | :-- | :-- |
      | **2 of 2 used** | <code>840c401</code> | <code>abcdef0</code> |

      ### Summary

      Further pushes will not start another automatic model review, and this pause notice will not be posted again.

      Comment \`@effect-agent review\` for another review of the latest changes, or \`@effect-agent review full\` for the full pull request diff.

      <sub>No model call · review automation paused at <code>abcdef0</code></sub>

      <!-- effect-agent-review-pause:v1 limit=2 -->"
    `);
  });

  it("shows the pause after a failed final automatic attempt", () => {
    expect(renderReviewFailureBody({ automaticReviewsRemaining: 0 })).toContain(
      "Automatic reviews are paused for this pull request.",
    );
    expect(renderReviewFailureBody({ automaticReviewsRemaining: 1 })).not.toContain(
      "Automatic reviews are paused",
    );
  });

  it("keeps untrusted unanchored text inside its disclosure", () => {
    const body = renderReviewBody({
      report: ReviewReport.make({
        summary: "One finding could contain markup.",
        findings: [
          ReviewFinding.make({
            path: "src/<projection>.ts",
            severity: "important",
            category: "correctness",
            title: "Unexpected </DETAILS > close",
            body: "The explanation contains <details>nested markup</details>.",
          }),
        ],
      }),
      automatic: false,
      automaticReviewsRemaining: 1,
      scope: "full",
      reviewedFiles: 1,
      unreviewedFiles: 0,
      ignoredFiles: 0,
      shards: 1,
      inputTokens: 100,
      uncachedInputTokens: 100,
      cachedInputTokens: 0,
      cacheWriteInputTokens: 0,
      outputTokens: 50,
      headRevision,
    });
    const unanchoredSection = body.slice(
      body.indexOf("<summary>Findings without an inline anchor"),
      body.indexOf("<summary>🤖 Prompt for all"),
    );

    expect(unanchoredSection).toContain("src/&lt;projection>.ts");
    expect(unanchoredSection).toContain("Unexpected &lt;/DETAILS > close");
    expect(unanchoredSection).toContain(
      "The explanation contains &lt;details>nested markup&lt;/details>.",
    );
    expect(unanchoredSection).not.toContain("</DETAILS >");
    expect(unanchoredSection).not.toContain("<details>nested markup");
  });
});

export type ReviewMode = "auto" | "incremental" | "full";

/** Parse a trusted collaborator command without admitting prefixes or trailing prose. */
export const reviewModeFromCommand = (command: string): "incremental" | "full" | undefined => {
  switch (command.trim()) {
    case "@effect-agent review":
    case "/effect-agent review":
      return "incremental";
    case "@effect-agent review full":
    case "/effect-agent review full":
      return "full";
    default:
      return undefined;
  }
};

export interface ReviewHistoryItem {
  readonly id: number;
  readonly authorLogin: string;
  readonly authorType: string;
  readonly body: string;
  readonly commitId: string | undefined;
  readonly submittedAt: string | undefined;
}

export type ReviewSelection =
  | {
      readonly _tag: "skip";
      readonly reason:
        | "head-already-reviewed"
        | "automatic-reviews-paused"
        | "incremental-baseline-unavailable";
    }
  | {
      readonly _tag: "pause";
      readonly reason: "automatic-reviews-paused";
      readonly automaticReviewLimit: number;
      readonly automaticAttempts: number;
      readonly lastCompletedRevision: string | undefined;
    }
  | {
      readonly _tag: "review";
      readonly scope: "full" | "incremental";
      readonly baseRevision: string | undefined;
      readonly automatic: boolean;
      readonly automaticReviewsRemaining: number;
      readonly reason: string;
    };

const ATTEMPT_MARKER_PATTERN =
  /(?:^|\n)<!-- effect-agent-review:v2 automatic=(true|false) completed=(true|false) -->\s*$/;
const PAUSE_MARKER_PATTERN = /(?:^|\n)<!-- effect-agent-review-pause:v1 limit=([0-9]+) -->\s*$/;

export const reviewMarker = (automatic: boolean, completed = true): string =>
  `<!-- effect-agent-review:v2 automatic=${String(automatic)} completed=${String(completed)} -->`;

export const reviewPauseMarker = (automaticReviewLimit: number): string =>
  `<!-- effect-agent-review-pause:v1 limit=${String(automaticReviewLimit)} -->`;

const markerKind = (
  body: string,
):
  | { readonly _tag: "attempt"; readonly automatic: boolean; readonly completed: boolean }
  | { readonly _tag: "pause"; readonly automaticReviewLimit: string }
  | undefined => {
  const attempt = ATTEMPT_MARKER_PATTERN.exec(body);
  if (attempt !== null) {
    return {
      _tag: "attempt",
      automatic: attempt[1] === "true",
      completed: attempt[2] === "true",
    };
  }
  const pause = PAUSE_MARKER_PATTERN.exec(body);
  return pause === null ? undefined : { _tag: "pause", automaticReviewLimit: pause[1] ?? "" };
};

/** Select scope from trusted GitHub reviews without persisting model context. */
export const selectReview = (input: {
  readonly mode: ReviewMode;
  readonly currentHead: string;
  readonly reviewAuthor: string;
  readonly automaticReviewLimit: number;
  readonly history: ReadonlyArray<ReviewHistoryItem>;
}): ReviewSelection => {
  const author = input.reviewAuthor.toLowerCase();
  const trusted = input.history
    .flatMap((item) => {
      const marker = markerKind(item.body);
      return marker !== undefined &&
        item.authorType === "Bot" &&
        item.authorLogin.toLowerCase() === author &&
        item.commitId !== undefined
        ? [{ item, marker }]
        : [];
    })
    .sort((left, right) => {
      const byTime = (left.item.submittedAt ?? "").localeCompare(right.item.submittedAt ?? "");
      return byTime === 0 ? left.item.id - right.item.id : byTime;
    });
  const attempts = trusted.flatMap(({ item, marker }) =>
    marker._tag === "attempt" ? [{ item, marker }] : [],
  );
  const automaticAttempts = attempts.filter(({ marker }) => marker.automatic).length;
  const automaticReviewsRemaining = Math.max(
    0,
    input.automaticReviewLimit - automaticAttempts - (input.mode === "auto" ? 1 : 0),
  );

  if (input.mode === "full") {
    return {
      _tag: "review",
      scope: "full",
      baseRevision: undefined,
      automatic: false,
      automaticReviewsRemaining,
      reason: "manual full review",
    };
  }

  if (
    attempts.some(
      ({ item, marker }) =>
        item.commitId === input.currentHead && (input.mode === "auto" || marker.completed),
    )
  ) {
    return { _tag: "skip", reason: "head-already-reviewed" };
  }

  if (input.mode === "auto" && automaticAttempts >= input.automaticReviewLimit) {
    if (input.automaticReviewLimit === 0) {
      return { _tag: "skip", reason: "automatic-reviews-paused" };
    }
    const pausePublished = trusted.some(
      ({ marker }) =>
        marker._tag === "pause" &&
        marker.automaticReviewLimit === String(input.automaticReviewLimit),
    );
    if (pausePublished) return { _tag: "skip", reason: "automatic-reviews-paused" };
    return {
      _tag: "pause",
      reason: "automatic-reviews-paused",
      automaticReviewLimit: input.automaticReviewLimit,
      automaticAttempts,
      lastCompletedRevision: attempts.filter(({ marker }) => marker.completed).at(-1)?.item
        .commitId,
    };
  }

  const latest = attempts.filter(({ marker }) => marker.completed).at(-1)?.item;
  if (latest?.commitId === undefined) {
    if (input.mode === "incremental") {
      return { _tag: "skip", reason: "incremental-baseline-unavailable" };
    }
    return {
      _tag: "review",
      scope: "full",
      baseRevision: undefined,
      automatic: input.mode === "auto",
      automaticReviewsRemaining,
      reason: "no prior review baseline",
    };
  }

  return {
    _tag: "review",
    scope: "incremental",
    baseRevision: latest.commitId,
    automatic: input.mode === "auto",
    automaticReviewsRemaining,
    reason: input.mode === "auto" ? "one automatic follow-up" : "manual incremental review",
  };
};

