    expect(result).toBe(reviewUrl);
    expect(reviewBody).toContain("Prompt for all 1 finding with AI agents");
    expect(yield* Ref.get(published)).toEqual(["POST /repos/reve-ai/example/pulls/12/reviews"]);
  }),
);

