+it.effect.each(["interrupt", "timeout"] as const)(
+  "closes without replay after dispatch on %s",
+  (mode) => {
+    const f = fixture();
+
+    return Effect.gen(function* () {
+      const entered = yield* Deferred.make<void>();
+      let writes = 0;
+
+      f.setFill(() =>
+        Effect.gen(function* () {
+          yield* (yield* ProtectedBrowserDispatch).mark;
+          writes++;
