  }).check(
    Schema.makeFilter(
      (viewport) =>
        Math.max(viewport.width, viewport.height) * (viewport.deviceScaleFactor ?? 1) <= 2_048,
      { title: "a viewport with scaled dimensions no larger than 2048 pixels" },
    ),
  ),
) {}

