const transportError = (reason: ProtectedTransportError["reason"]) =>
  new ProtectedTransportError({ reason });

const decode = <A>(schema: Schema.Codec<A>, value: unknown) =>
  Schema.decodeUnknownEffect(schema)(value).pipe(Effect.mapError(() => transportError("provider")));

// Attach rejection handling inside the SDK callback before workerd can report foreign diagnostics.
const remote = <A>(run: (signal: AbortSignal) => Promise<A>) =>
  Effect.tryPromise({
    try: async (signal) => {
      try {
        return { ok: true as const, value: await run(signal) };
      } catch {
        return { ok: false as const };
      }
    },
    catch: () => transportError("provider"),
  }).pipe(
    Effect.flatMap((result) =>
      result.ok ? Effect.succeed(result.value) : Effect.fail(transportError("provider")),
    ),
  );

/** Host-private scoped transport. Session capabilities are requirements; policy is per-pass data. */
export const makeProtectedNativeTransport = Effect.fn("ProtectedNativeTransport.make")(function* (
  policy: InteractiveBrowserPolicy,
): Effect.fn.Return<
  ProtectedBrowserTransport,
  never,
  ProtectedNativeSession | Crypto.Crypto | Scope.Scope
> {
  const session = yield* ProtectedNativeSession;
  const { browser, page } = session;
  const crypto = yield* Crypto.Crypto;
  const clock = yield* Clock.Clock;
  const uuid = crypto.randomUUIDv4.pipe(Effect.mapError(() => transportError("provider")));
  let closed = false;
  let violation = false;
  let documentRef: string | undefined;
  const frames = new Map<Frame, FrameState>();
  const controls = new Map<string, ControlState>();

  const origin = (value: string) =>
    Effect.try({
      try: () => {
        const url = new URL(value);

        if (url.username || url.password) throw transportError("stale-reference");
        if (!Schema.is(CredentialOrigin)(url.origin)) throw transportError("unsupported");
        if (policy.network._tag === "ExactHosts" && !policy.network.allowedHosts.includes(url.host))
          throw transportError("stale-reference");

        return url.origin;
      },
      catch: (cause) =>
        Schema.is(ProtectedTransportError)(cause) ? cause : transportError("provider"),
    });

  const check = Effect.suspend(() =>
    closed || violation || !browser.isConnected()
      ? Effect.fail(transportError("stale-reference"))
      : Effect.void,
  );

  const clear = () => {
    controls.clear();
    // Browser event callbacks only invalidate. The next Effect operation allocates the new identity.
    documentRef = undefined;
  };

  const onNavigated = () => {
    clear();
  };

  const onTarget = (target: { type(): string }) => {
    if (target.type() !== "page") return;
    // No popup or additional page may inherit an observation channel.
    violation = true;
    clear();
  };

  const invalidate = () => {
    closed = true;
    clear();
  };

  const context = Effect.gen(function* () {
    yield* check;
    const list = page.frames();

    if (list.length > 16) return yield* transportError("unsupported");
    const topOrigin = yield* origin(page.url());
    const frameOrigins = yield* Effect.forEach(list, (frame) => origin(frame.url()));

    if (documentRef === undefined) documentRef = yield* uuid;

    return yield* decode(ProtectedPageContext, { document: documentRef, topOrigin, frameOrigins });
  });

  const isCurrent = Effect.fn("ProtectedNativeTransport.isCurrent")(function* (state: FrameState) {
    if (state.frame.detached) return false;

    return yield* remote(() =>
      state.handle.evaluate((held) => {
        if (typeof held !== "object" || held === null) return false;

        return Reflect.get(held, "doc") === Reflect.get(globalThis, "document");
      }),
    );
  });

  const get = Effect.fn("ProtectedNativeTransport.get")(function* (ref: string) {
    yield* check;
    const state = controls.get(ref);

    if (
      !state ||
      state.expires <= (yield* clock.currentTimeMillis) ||
      !(yield* isCurrent(state.frame))
    )
      return yield* transportError("stale-reference");

    const current = yield* remote(() =>
      state.frame.handle.evaluate((held, index) => {
        if (typeof held !== "object" || held === null) return null;

        return Reflect.apply(Reflect.get(held, "validate"), held, [index]);
      }, state.index),
    );

    const description = yield* decode(Schema.NullOr(Description), current);

    if (description === null) return yield* transportError("stale-reference");
    const ctx = yield* context;

    if (
      ctx.topOrigin !== state.control.target.topOrigin ||
      (yield* origin(state.frame.frame.url())) !== state.control.target.frameOrigin ||
      (yield* origin(description.action)) !== state.control.target.recipientOrigin ||
      description.role !== state.control.role
    )
      return yield* transportError("stale-reference");

    return state;
  });

  const close = yield* Effect.cached(
    Effect.gen(function* () {
      invalidate();

      return yield* session.close;
    }).pipe(
      Effect.ensuring(
        Effect.sync(() => {
          page.off("framenavigated", onNavigated);
          page.off("framedetached", onNavigated);
          browser.off("targetcreated", onTarget);
          // Handles die with the exact session. Do not block remote termination on local disposal.
          frames.clear();
        }),
      ),
    ),
  );

  yield* Effect.acquireRelease(
    Effect.sync(() => {
      page.on("framenavigated", onNavigated);
      page.on("framedetached", onNavigated);
      browser.on("targetcreated", onTarget);
    }),
    () => close,
  );

  return {
    context,
    invalidate,
    close,
    navigate: Effect.fn("ProtectedNativeTransport.navigate")(function* (url) {
      yield* check;
      yield* origin(url);
      clear();
      yield* remote(() => page.goto(url, { waitUntil: "load" }));
      yield* context;
    }),
    target: (ref) => get(ref).pipe(Effect.map((state) => state.control)),
    discover: Effect.gen(function* () {
      const before = yield* context;

      controls.clear();
      for (const state of frames.values()) yield* remote(() => state.handle.dispose());
      frames.clear();
      const discovered: Array<ProtectedBrowserControl> = [];
      let text = "";
      let truncated = false;

      for (const frame of page.frames()) {
        if (typeof frame.isolatedRealm !== "function") return yield* transportError("unsupported");
        const handle = yield* remote(() => frame.isolatedRealm().evaluateHandle(inspectFrame));

        const state: FrameState = {
          frame,
          handle,
          ref: yield* uuid,
          document: yield* uuid,
          forms: new Map(),
        };

        frames.set(frame, state);

        const raw = yield* remote(() =>
          handle.evaluate((held) => {
            if (typeof held !== "object" || held === null) return null;

            return Reflect.get(held, "original");
          }),
        );

        const descriptions = yield* decode(Descriptions, raw);

        for (let index = 0; index < descriptions.length; index++) {
          const desc = descriptions[index];

          if (!desc) continue;
          if (discovered.length === 64) {
            truncated = true;
            break;
          }
          let form = state.forms.get(desc.formIndex);

          if (form === undefined) {
            form = yield* uuid;
            state.forms.set(desc.formIndex, form);
          }
          // Unsupported destinations/controls are not offered as credential targets.
          const recipient = yield* origin(desc.action).pipe(Effect.result);

          if (recipient._tag === "Failure") continue;

          const control = ProtectedBrowserControl.make({
            ref: yield* uuid,
            role: desc.role,
            label: desc.label,
            target: CredentialTarget.make({
              topOrigin: before.topOrigin,
              frameOrigin: yield* origin(frame.url()),
              recipientOrigin: recipient.success,
              document: state.document,
              frame: state.ref,
              form,
            }),
          });

          controls.set(control.ref, {
            frame: state,
            index,
            control,
            expires: (yield* clock.currentTimeMillis) + 60_000,
          });
          discovered.push(control);
        }

        const rawText = yield* remote(() =>
          handle.evaluate((held) => {
            if (typeof held !== "object" || held === null) return null;

            return Reflect.apply(Reflect.get(held, "text"), held, []);
          }),
        );

        text += yield* decode(Schema.String.check(Schema.isMaxLength(65536)), rawText);
        if (text.length > 65536) {
          text = text.slice(0, 65536);
          truncated = true;
        }
      }
      if ((yield* context).document !== before.document)
        return yield* transportError("stale-reference");

      return yield* decode(ProtectedDiscovery, {
        ...before,
        text,
        controls: discovered,
        truncated,
      });
    }),
    fill: Effect.fn("ProtectedNativeTransport.fill")(function* (ref, role, value) {
      const dispatch = yield* ProtectedBrowserDispatch;
      const state = yield* get(ref);

      // CDP dispatch may mutate before its reply is lost, so uncertainty starts here.
      yield* dispatch.mark;

      const filled = yield* remote(() =>
        state.frame.handle.evaluate(
          (held, index, expectedRole, secret) => {
            if (typeof held !== "object" || held === null) return false;

            return Reflect.apply(Reflect.get(held, "fill"), held, [index, expectedRole, secret]);
          },
          state.index,
          role,
          Redacted.value(value),
        ),
      );

      if (filled === "unsupported") return yield* transportError("unsupported");
      if (filled !== true) return yield* transportError("stale-reference");
    }),
    click: Effect.fn("ProtectedNativeTransport.click")(function* (ref) {
      const state = yield* get(ref);

      const clicked = yield* remote(() =>
        state.frame.handle.evaluate((held, index) => {
          if (typeof held !== "object" || held === null) return false;

          return Reflect.apply(Reflect.get(held, "click"), held, [index]);
        }, state.index),
      );

      if (clicked === "needs-attention") return yield* transportError("needs-attention");
      if (clicked !== true) return yield* transportError("stale-reference");
    }),
  };
}, Effect.withTracerEnabled(false));

/// <reference types="@cloudflare/workers-types" />
import {
  BrowserCredentialAccess,
  type BrowserCredentialMaterial,
  CardCredential,
  CredentialOffer,
  CredentialOfferMetadata,
  CredentialOrigin,
  type CredentialTarget,
  CredentialUseResult,
  InteractiveBrowserPolicy,
  ListCredentialOffers,
  LoginCredential,
  ProtectedBrowser,
  ProtectedBrowserClick,
  ProtectedBrowserError,
  ProtectedBrowserNavigate,
  ProtectedBrowserObservation,
  ProtectedBrowserControl,
  UseCredential,
  type CredentialFieldRole,
  type CredentialKind,
  type CredentialUseAuthorization,
  type ProtectedBrowserHandle,
  type ProtectedCleanup,
  type ProtectedObservationState,
} from "@effect-agent/sandbox";
import {
  Clock,
  Context,
  Crypto,
  Effect,
  Layer,
  Option,
  Redacted,
  Schema,
  Semaphore,
  type Scope,
} from "effect";

export class ProtectedTransportError extends Schema.TaggedError<ProtectedTransportError>()(
  "ProtectedTransportError",
  { reason: Schema.Literals(["stale-reference", "needs-attention", "unsupported", "provider"]) },
) {}

/** Per-write evidence authority, provided by the policy immediately around a transport fill. */
export class ProtectedBrowserDispatch extends Context.Service<
  ProtectedBrowserDispatch,
  { readonly mark: Effect.Effect<void> }
>()("@effect-agent/platform-cloudflare/ProtectedBrowserDispatch") {}

/** Decoded adapter boundary. SDK exceptions and page diagnostics never cross this port. */
export interface ProtectedBrowserTransport {
  readonly context: Effect.Effect<typeof ProtectedPageContext.Type, ProtectedTransportError>;
  readonly discover: Effect.Effect<typeof ProtectedDiscovery.Type, ProtectedTransportError>;
  readonly target: (ref: string) => Effect.Effect<ProtectedBrowserControl, ProtectedTransportError>;
  readonly navigate: (url: string) => Effect.Effect<void, ProtectedTransportError>;
  readonly click: (ref: string) => Effect.Effect<void, ProtectedTransportError>;
  readonly fill: (
    ref: string,
    role: typeof CredentialFieldRole.Type,
    value: Redacted.Redacted<string>,
  ) => Effect.Effect<void, ProtectedTransportError, ProtectedBrowserDispatch>;
  /** Invalidates local references synchronously before bounded exact-session cleanup. */
  readonly invalidate: () => void;
  readonly close: Effect.Effect<typeof ProtectedCleanup.Type>;
}

/** Adapter-private injection seam for deterministic tests, not a model capability. */
export class BrowserRunProtectedTransport extends Context.Service<
  BrowserRunProtectedTransport,
  {
    readonly open: (
      policy: InteractiveBrowserPolicy,
    ) => Effect.Effect<ProtectedBrowserTransport, ProtectedBrowserError, Scope.Scope>;
  }
>()("@effect-agent/platform-cloudflare/BrowserRunProtectedTransport") {}

export const ProtectedPageContext = Schema.Struct({
  document: Schema.String.check(Schema.isUUID()),
  topOrigin: CredentialOrigin,
  frameOrigins: Schema.Array(CredentialOrigin).check(Schema.isMaxLength(16)),
});

export const ProtectedDiscovery = Schema.Struct({
  ...ProtectedPageContext.fields,
  text: Schema.String.check(Schema.isMaxLength(64 * 1024)),
  controls: Schema.Array(ProtectedBrowserControl).check(Schema.isMaxLength(64)),
  truncated: Schema.Boolean,
});

const sameTarget = (a: CredentialTarget, b: CredentialTarget) =>
  a.topOrigin === b.topOrigin &&
  a.frameOrigin === b.frameOrigin &&
  a.recipientOrigin === b.recipientOrigin &&
  a.document === b.document &&
  a.frame === b.frame &&
  a.form === b.form;

const kindFor = (role: string): typeof CredentialKind.Type | undefined =>
  role === "username" || role === "password"
    ? "login"
    : role.startsWith("card-")
      ? "card"
      : undefined;

const secretFor = (material: BrowserCredentialMaterial, role: typeof CredentialFieldRole.Type) => {
  if (material._tag === "LoginCredential") {
    return role === "username"
      ? material.username
      : role === "password"
        ? material.password
        : undefined;
  }
  switch (role) {
    case "card-name":
      return material.name;
    case "card-number":
      return material.number;
    case "card-expiry":
      return material.expiry;
    case "card-expiry-month":
      return material.expiryMonth;
    case "card-expiry-year":
      return material.expiryYear;
    case "card-security-code":
      return material.securityCode;
    case "username":
    case "password":
      return undefined;
  }
};

/**
 * Fresh private passes only. Account administrators and Browser Rendering token holders are
 * trusted operators. No viewer, handoff, raw JavaScript, screenshot or plaintext-fill API exists.
 * Hosts explicitly authorize post-exposure observations for recipients they trust not to echo.
 */
export const browserRunProtectedLayer = () =>
  Layer.effect(ProtectedBrowser)(
    Effect.gen(function* () {
      const transport = yield* BrowserRunProtectedTransport;
      const crypto = yield* Crypto.Crypto;

      const open = Effect.fn("ProtectedBrowser.open")(function* (
        input: InteractiveBrowserPolicy,
      ): Effect.fn.Return<
        ProtectedBrowserHandle,
        ProtectedBrowserError,
        Scope.Scope | BrowserCredentialAccess
      > {
        const initialError = (reason: ProtectedBrowserError["reason"]) =>
          new ProtectedBrowserError({
            reason,
            dispatch: "not-dispatched",
            milestone: "none",
            observation: "closed",
            cleanup: "not-requested",
          });

        const decodedPolicy = yield* Schema.decodeUnknownEffect(InteractiveBrowserPolicy)(
          input,
        ).pipe(Effect.mapError(() => initialError("denied")));

        if (decodedPolicy.network._tag === "PublicWeb") return yield* initialError("unsupported");

        const policy = InteractiveBrowserPolicy.make({
          ...decodedPolicy,
          network:
            decodedPolicy.network._tag === "ExactHosts"
              ? { _tag: "ExactHosts", allowedHosts: [...decodedPolicy.network.allowedHosts] }
              : { _tag: "Unrestricted" },
        });

        // Capture the host access service for THIS execution, not the application singleton.
        const access = yield* BrowserCredentialAccess;
        const started = yield* Clock.currentTimeMillis;
        const driver = yield* transport.open(policy);
        const lock = yield* Semaphore.make(1);
        let observation: typeof ProtectedObservationState.Type = "before-exposure";
        let cleanup: typeof ProtectedCleanup.Type = "not-requested";
        let actions = 0;
        let dispatch: ProtectedBrowserError["dispatch"] = "not-dispatched";
        let milestone: ProtectedBrowserError["milestone"] = "none";
        const exposures: Array<CredentialTarget> = [];

        const offers = new Map<
          string,
          {
            caller: Redacted.Redacted<string>;
            key: Redacted.Redacted<string>;
            target: CredentialTarget;
            targetRef: string;
            kind: typeof CredentialKind.Type;
            expires: number;
          }
        >();

        const fail = (reason: ProtectedBrowserError["reason"]) =>
          new ProtectedBrowserError({ reason, dispatch, milestone, observation, cleanup });

        const close = yield* Effect.cached(
          Effect.uninterruptible(
            Effect.gen(function* () {
              observation = "closed";
              offers.clear();
              driver.invalidate();
              cleanup = yield* driver.close.pipe(
                Effect.interruptible,
                Effect.timeoutOrElse({
                  duration: "10 seconds",
                  orElse: () => Effect.succeed("unconfirmed" as const),
                }),
                Effect.catchCause(() => Effect.succeed("unconfirmed" as const)),
              );

              return cleanup;
            }),
          ),
        );

        yield* Effect.addFinalizer(() =>
          close.pipe(
            Effect.flatMap((result) =>
              result === "unconfirmed"
                ? Effect.logWarning("Protected browser exact-session closure unconfirmed")
                : Effect.void,
            ),
          ),
        );

        const remote = <A, R>(effect: Effect.Effect<A, ProtectedTransportError, R>) =>
          effect.pipe(Effect.mapError((error) => fail(error.reason)));

        const decode = <A>(schema: Schema.Codec<A>, value: unknown) =>
          Schema.decodeUnknownEffect(schema)(value).pipe(Effect.mapError(() => fail("provider")));

        const caller = access.caller.pipe(Effect.mapError((error) => fail(error.reason)));
        const pageContext = remote(driver.context);

        const permitObservation = Effect.gen(function* () {
          const context = yield* pageContext;

          if (exposures.length > 0) {
            observation = "protected";

            const decision = yield* access
              .observation({ ...context, caller: yield* caller, exposures: [...exposures] })
              .pipe(Effect.mapError((error) => fail(error.reason)));

            if (decision !== "trust-recipient-no-credential-echo")
              return yield* fail("observation-blocked");
            observation = "approved-after-exposure";
          }

          return context;
        });

        const target = (ref: string) => remote(driver.target(ref));

        const bounded = <A>(result: A) => {
          const bytes = new TextEncoder().encode(JSON.stringify(result)).byteLength;

          return bytes <= policy.maxReturnedBytes
            ? Effect.succeed(result)
            : Effect.fail(fail("limit"));
        };

        const run = <A>(effect: Effect.Effect<A, ProtectedBrowserError>) =>
          lock
            .withPermitsIfAvailable(1)(
              Effect.gen(function* () {
                dispatch = "not-dispatched";
                milestone = "none";
                if (observation === "closed") return yield* fail("closed");
                if (++actions > policy.maxActions) return yield* fail("limit");

                const remaining =
                  policy.maxElapsedMillis - ((yield* Clock.currentTimeMillis) - started);

                if (remaining <= 0) {
                  yield* close;

                  return yield* fail("timeout");
                }

                return yield* effect.pipe(
                  Effect.timeoutOrElse({
                    duration: remaining,
                    orElse: () => Effect.fail(fail("timeout")),
                  }),
                  Effect.catchCause((cause) =>
                    Effect.gen(function* () {
                      // No foreign exception or defect is retained. Interrupted operations still finalize.
                      const error = cause.reasons.find(
                        (reason) =>
                          reason._tag === "Fail" && Schema.is(ProtectedBrowserError)(reason.error),
                      );

                      const reason =
                        error?._tag === "Fail" && Schema.is(ProtectedBrowserError)(error.error)
                          ? error.error.reason
                          : "provider";

                      const interrupt = cause.reasons.some((reason) => reason._tag === "Interrupt");

                      if (
                        dispatch !== "not-dispatched" ||
                        interrupt ||
                        reason === "provider" ||
                        reason === "timeout"
                      )
                        yield* close;
                      if (interrupt) return yield* Effect.interrupt;

                      return yield* fail(
                        dispatch === "possibly-dispatched" && reason === "provider"
                          ? "outcome-unknown"
                          : reason,
                      );
                    }),
                  ),
                  Effect.onInterrupt(() => close),
                  Effect.withTracerEnabled(false),
                );
              }),
            )
            .pipe(
              Effect.flatMap((result) =>
                Option.isSome(result)
                  ? Effect.succeed(result.value)
                  : Effect.fail(
                      new ProtectedBrowserError({
                        reason: "busy",
                        dispatch: "not-dispatched",
                        milestone: "none",
                        observation,
                        cleanup,
                      }),
                    ),
              ),
            );

        return {
          close,
          navigate: (request) =>
            run(
              Effect.gen(function* () {
                const decoded = yield* Schema.decodeUnknownEffect(ProtectedBrowserNavigate)(
                  request,
                ).pipe(Effect.mapError(() => fail("denied")));

                let url: URL;

                try {
                  url = new URL(decoded.url);
                } catch {
                  return yield* fail("denied");
                }
                if (
                  url.protocol !== "https:" ||
                  url.username ||
                  url.password ||
                  (policy.network._tag === "ExactHosts" &&
                    !policy.network.allowedHosts.includes(url.host))
                )
                  return yield* fail("denied");
                if (exposures.length > 0) yield* permitObservation;
                offers.clear();
                dispatch = "possibly-dispatched";
                yield* remote(driver.navigate(decoded.url));
                dispatch = "dispatched";
                yield* permitObservation;
              }),
            ),
          observe: run(
            Effect.gen(function* () {
              const before = yield* permitObservation;
              const result = yield* remote(driver.discover);
              const after = yield* permitObservation;

              if (before.document !== after.document || result.document !== after.document)
                return yield* fail("stale-reference");

              return yield* bounded(
                ProtectedBrowserObservation.make({
                  ...result,
                  observation: exposures.length > 0 ? "approved-after-exposure" : "before-exposure",
                }),
              );
            }),
          ),
          click: (request) =>
            run(
              Effect.gen(function* () {
                const decoded = yield* Schema.decodeUnknownEffect(ProtectedBrowserClick)(
                  request,
                ).pipe(Effect.mapError(() => fail("denied")));

                yield* permitObservation;
                const control = yield* target(decoded.ref);

                // Credential submission goes through useCredential, never a generic click.
                if (control.role !== "link" && control.role !== "button")
                  return yield* fail("unsupported");
                dispatch = "possibly-dispatched";
                yield* remote(driver.click(decoded.ref));
                dispatch = "dispatched";
                yield* permitObservation;
              }),
            ),
          listCredentialOffers: (request) =>
            run(
              Effect.gen(function* () {
                const decoded = yield* Schema.decodeUnknownEffect(ListCredentialOffers)(
                  request,
                ).pipe(Effect.mapError(() => fail("denied")));

                yield* permitObservation;
                const control = yield* target(decoded.target);

                if (kindFor(control.role) !== decoded.kind) return yield* fail("unsupported");
                const principal = yield* caller;

                const candidates = yield* access
                  .list({ caller: principal, kind: decoded.kind, target: control.target })
                  .pipe(Effect.mapError((error) => fail(error.reason)));

                const now = yield* Clock.currentTimeMillis;

                for (const [ref, offer] of offers) if (offer.expires <= now) offers.delete(ref);
                if (candidates.length > 16 || offers.size + candidates.length > 64)
                  return yield* fail("limit");
                if (!sameTarget(control.target, (yield* target(decoded.target)).target))
                  return yield* fail("stale-reference");
                const expires = now + 60_000;
                const result: Array<CredentialOffer> = [];
                const pending: typeof offers = new Map();

                for (const candidate of candidates) {
                  const metadata = yield* decode(CredentialOfferMetadata, candidate.metadata);

                  const ref = yield* crypto.randomUUIDv4.pipe(
                    Effect.mapError(() => fail("provider")),
                  );

                  pending.set(ref, {
                    caller: principal,
                    key: candidate.key,
                    target: control.target,
                    targetRef: decoded.target,
                    kind: decoded.kind,
                    expires,
                  });
                  result.push(CredentialOffer.make({ ref, kind: decoded.kind, metadata }));
                }
                yield* bounded(result);
                for (const [ref, offer] of pending) offers.set(ref, offer);

                return result;
              }),
            ),
          useCredential: (request) =>
            run(
              Effect.gen(function* () {
                const decoded = yield* Schema.decodeUnknownEffect(UseCredential)(request).pipe(
                  Effect.mapError(() => fail("denied")),
                );

                const offer = offers.get(decoded.offer);

                if (offer === undefined || offer.expires <= (yield* Clock.currentTimeMillis))
                  return yield* fail("stale-reference");
                const principal = yield* caller;

                if (Redacted.value(principal) !== Redacted.value(offer.caller))
                  return yield* fail("denied");
                if (offer.kind === "card" && decoded.submit !== undefined)
                  return yield* fail("unsupported");
                if (
                  new Set(decoded.fields.map((field) => field.ref)).size !==
                    decoded.fields.length ||
                  new Set(decoded.fields.map((field) => field.role)).size !== decoded.fields.length
                )
                  return yield* fail("denied");

                const validate = Effect.gen(function* () {
                  if (!sameTarget(offer.target, (yield* target(offer.targetRef)).target))
                    return yield* fail("stale-reference");
                  for (const field of decoded.fields) {
                    const current = yield* target(field.ref);

                    if (
                      field.role !== current.role ||
                      kindFor(field.role) !== offer.kind ||
                      !sameTarget(offer.target, current.target)
                    )
                      return yield* fail("denied");
                  }
                  if (decoded.submit !== undefined) {
                    const submit = yield* target(decoded.submit);

                    if (submit.role !== "submit" || !sameTarget(offer.target, submit.target))
                      return yield* fail("denied");
                  }
                });

                yield* validate;

                const authorization: CredentialUseAuthorization = {
                  caller: principal,
                  key: offer.key,
                  kind: offer.kind,
                  target: offer.target,
                  roles: decoded.fields.map((field) => field.role),
                  submit: decoded.submit !== undefined,
                };

                const authorize = Effect.gen(function* () {
                  if (Redacted.value(yield* caller) !== Redacted.value(principal))
                    return yield* fail("denied");
                  yield* access
                    .authorize(authorization)
                    .pipe(Effect.mapError((error) => fail(error.reason)));
                });

                yield* authorize;
                yield* validate;

                const raw = yield* access
                  .resolve(authorization)
                  .pipe(Effect.mapError((error) => fail(error.reason)));

                const material = yield* Schema.decodeUnknownEffect(
                  offer.kind === "login" ? LoginCredential : CardCredential,
                )(raw).pipe(Effect.mapError(() => fail("resolver")));

                for (const field of decoded.fields)
                  if (secretFor(material, field.role) === undefined)
                    return yield* fail("missing-credential");
                offers.delete(decoded.offer);
                for (const field of decoded.fields) {
                  yield* validate;
                  yield* authorize;
                  const value = secretFor(material, field.role);

                  if (value === undefined) return yield* fail("missing-credential");
                  observation = "protected";
                  yield* remote(driver.fill(field.ref, field.role, value)).pipe(
                    Effect.provideService(ProtectedBrowserDispatch, {
                      mark: Effect.sync(() => {
                        dispatch = "possibly-dispatched";
                        if (!exposures.some((target) => sameTarget(target, offer.target)))
                          exposures.push(offer.target);
                      }),
                    }),
                  );
                  dispatch = "dispatched";
                  milestone = "partial-fill";
                }
                milestone = "filled";
                if (decoded.submit !== undefined) {
                  yield* validate;
                  yield* authorize;
                  const ref = decoded.submit;

                  dispatch = "possibly-dispatched";
                  yield* remote(driver.click(ref)).pipe(
                    Effect.catch((error) => {
                      if (error.reason === "needs-attention") dispatch = "dispatched";

                      return Effect.fail(error);
                    }),
                  );
                  dispatch = "dispatched";
                  milestone = "submission-dispatched";
                }
                yield* permitObservation;

                return CredentialUseResult.make({
                  dispatch,
                  milestone,
                  observation,
                  cleanup,
                  authentication: "unverified",
                });
              }),
            ),
        };
      }, Effect.withTracerEnabled(false));

      return { open };
    }),
  );

import {
  type MemoryLookup,
  MemoryAccess,
  MemoryScope,
  MemoryMutationFailpoint,
  MemoryMutationFailure,
  MemoryNamespace,
  MemoryPassage,
  MemoryRecallLimits,
  MemoryWrite,
  type MemoryMutationPoint,
} from "@effect-agent/core";
import {
  MemoryOwnerAuthorizer,
  MemoryOwnerIdentity,
  MemoryRpcError,
} from "@effect-agent/storage-cloudflare";
import { Principal } from "@effect-agent/thread";
import { Clock, Deferred, Effect, Layer, Schema } from "effect";
import { DurableObjectState } from "effect-cf";

export const MemoryProjects = MemoryNamespace.define({
  name: "test/projects",
  version: 1,
  identity: Schema.String,
});

export const memoryScope = MemoryScope.make("team");
export const memoryPrincipal = Principal.make("application");

export const memoryAccess = (project: string) =>
  MemoryAccess.make({ namespace: MemoryProjects.make(project), scope: memoryScope });

export const memoryRecallLimits = MemoryRecallLimits.make({
  maxSources: 16,
  maxItems: 128,
  maxBytes: 100_000,
  maxTokens: 100_000,
  maxInputBytes: 1_000_000,
  timeoutMillis: 1_000,
});

export const memoryPut = (
  project: string,
  id: string,
  operationId = `put-${id}`,
  expectedRevision: string | null = null,
  text = `text-${id}`,
) => {
  const write = MemoryWrite.make({
    _tag: "Put",
    key: { namespace: MemoryProjects.make(project), id },
    operationId,
    expectedRevision,
    locator: `memory://${id}`,
    scopes: [memoryScope],
    content: {
      text,
      attributions: [
        {
          originId: `origin-${id}`,
          speaker: "Dan",
          observers: ["caller-a"],
          locator: "thread://a/input",
          activityAt: 1,
          interpretation: "statement",
        },
      ],
      metadata: {},
      recordedAt: 2,
    },
  });

  if (write._tag !== "Put") throw new Error("Expected Put fixture");

  return write;
};

export const memoryCandidates = (ids: ReadonlyArray<string>): MemoryLookup => ({
  _tag: "Found",
  passages: ids.map((id) =>
    MemoryPassage.make({
      version: 1,
      source: { id, revision: "stale", locator: "cache://not-authoritative" },
      passageId: "cached",
      content: memoryPut("ignored", id).content,
    }),
  ),
});

export const memoryCalls = new Map<string, number>();

export const memoryFaults = new Map<
  string,
  { point: MemoryMutationPoint; kind: "fail" | "abort" }
>();

export const slowStarted = new Map<string, Deferred.Deferred<void>>();
export const slowFinished = new Map<string, Deferred.Deferred<void>>();
export const memoryClocks = new Map<string, Clock.Clock>();

export const memoryAuthorizer = Layer.effect(
  MemoryOwnerAuthorizer,
  Effect.gen(function* () {
    const { namespace } = yield* MemoryOwnerIdentity;

    yield* MemoryProjects.restore(namespace.address);

    return {
      authorize: Effect.fn("test.memory.authorize")(function* (request) {
        if (request.principal === "defect") return yield* Effect.die("authorization defect");
        if (request.principal === "slow") {
          return yield* Effect.acquireUseRelease(
            Effect.gen(function* () {
              const started = slowStarted.get(namespace.address);

              if (started) yield* Deferred.succeed(started, undefined);
            }),
            () => Effect.never,
            () =>
              Effect.gen(function* () {
                const finished = slowFinished.get(namespace.address);

                if (finished) yield* Deferred.succeed(finished, undefined);
              }),
          );
        }
        if (request.principal !== memoryPrincipal || request.access.scope !== memoryScope)
          return yield* MemoryRpcError.make({ reason: "denied" });
      }),
    };
  }),
).pipe(
  Layer.merge(
    Layer.effect(Clock.Clock)(
      Effect.gen(function* () {
        const { namespace } = yield* MemoryOwnerIdentity;

        return memoryClocks.get(namespace.address) ?? (yield* Clock.Clock);
      }),
    ),
  ),
);

export const memoryFailpoints = Layer.effect(
  MemoryMutationFailpoint,
  Effect.gen(function* () {
    const state = yield* DurableObjectState.DurableObjectState;

    return {
      hit: (point: MemoryMutationPoint) =>
        Effect.suspend(() => {
          const name = state.raw.id.name ?? "";
          const fault = memoryFaults.get(name);

          if (!fault || fault.point !== point) return Effect.void;
          memoryFaults.delete(name);

          return fault.kind === "fail"
            ? Effect.fail(MemoryMutationFailure.make({ point }))
            : Effect.sync(() => state.raw.abort(`memory fault ${point}`));
        }),
    };
  }),
);

